import {traceWindow,traceKeys,clearTrace,recordTrace,stepPath,selectTrace,moveTrace,tracePoints} from './trends-model.mjs';
const labels=['a0 / I0.0','a1 / I0.1','b0 / I0.2','b1 / I0.3','YA / Q0.0','YB / Q0.1','PS / I0.4','FALLO'];
export function createTrends(root,{trace,onPlay,onScan,onInspect}){const panel=document.createElement('section');panel.className='hmi-trends';panel.innerHTML=`<div class="trend-heading"><div><span class="eyebrow">TENDENCIAS / UN PUNTO POR SCAN · 20 ms</span><h3>De la orden al movimiento</h3></div><label>Ventana <select id="trendSpan"><option value="10">10 s</option><option value="30" selected>30 s</option><option value="60">60 s</option></select></label><button id="trendPlay">Pausar simulación</button><button id="trendScan">+1 scan</button><button id="trendClear">Limpiar trazas</button></div><p>Tiempo simulado común al PLC, al ladder y a las piezas. A: línea verde continua · B: línea azul discontinua. Las pistas digitales muestran 0 abajo y 1 arriba. Abajo: presión del modelo en bar; línea discontinua = umbral de 3 bar.</p><div class="trend-scroll" tabindex="0" aria-label="Gráficas de posiciones y señales; desplaza horizontalmente en pantallas pequeñas"><svg id="trendChart" viewBox="0 0 1000 850" role="img" aria-label="Historial sincronizado de posiciones y señales del PLC"></svg></div><div class="trend-inspection"><strong id="trendMode">Estado actual</strong><label>Instante del historial <input id="trendCursor" type="range" min="0" max="0" step="0.02" value="0"></label><div class="hmi-actions"><button id="tracePrev">−1 muestra</button><button id="traceNext">+1 muestra</button><button id="tracePrevEvent">Evento anterior</button><button id="traceNextEvent">Evento siguiente</button><button id="traceFault">Último fallo</button><button id="traceLive">Volver al actual</button></div><p>Pulsa la gráfica o mueve el cursor. Seleccionar pausa la simulación y muestra el ladder guardado de ese scan. HMI y circuito 3D conservan el estado actual. Los eventos son cambios de entradas, salidas o FALLO. Volver al actual no reanuda automáticamente.</p></div><p id="trendReadout" aria-live="polite"></p><details><summary>Cómo interpretar las gráficas</summary><p>La salida cambia al final del scan. La posición responde durante el scan siguiente. Al llegar al extremo cambia su sensor; durante el TON la posición queda horizontal. Q0.0 permanece en 1 durante el avance y retorno de B. Las líneas verticales de las señales son cambios digitales, no rampas.</p><p>PS=0 provoca fallo y retira las salidas. Un atasco deja la posición horizontal aunque exista orden; en automático, la falta de sensor termina en timeout. FALLO queda retenido hasta rearme. Se conservan hasta 60 segundos de muestras en memoria. Pausar congela todo; cambiar la velocidad visual no cambia la escala en segundos. Limpiar trazas no modifica el PLC ni el contador. Reiniciar la simulación comienza un historial nuevo. Posiciones del modelo, sin adquisición de hardware.</p></details>`;root.append(panel);
 const q=s=>panel.querySelector(s);let last='',current=null,span=30,windowStart=0;const render=()=>{if(!current)return;const {s,playing,disabled}=current;q('#trendPlay').textContent=playing?'Pausar simulación':'Reanudar simulación';q('#trendPlay').disabled=q('#trendScan').disabled=disabled;for(const id of ['trendCursor','tracePrev','traceNext','tracePrevEvent','traceNextEvent','traceFault'])q('#'+id).disabled=disabled;const selected=trace.selected,shown=selected?.snapshot||s;const points=tracePoints(trace);q('#traceFault').disabled=disabled||!points.some((p,i)=>i>0&&p.fault&&!points[i-1].fault);q('#trendCursor').min=points[0]?.time||0;q('#trendCursor').max=points.at(-1)?.time||0;q('#trendCursor').value=shown.time;q('#trendMode').textContent=selected?'HISTORIAL · '+shown.time.toFixed(2)+' s · ladder de este scan':'ESTADO ACTUAL · '+s.time.toFixed(2)+' s';const key=trace.version+':'+span+':'+(selected?.time??'live');if(key===last)return;last=key;const w=traceWindow(trace,selected?Math.min(s.time,selected.time+span/2):s.time,span),x=t=>+(110+(t-w.start)/span*860).toFixed(2);windowStart=w.start;let svg='<defs><clipPath id="trendClip"><rect x="110" y="25" width="860" height="780"/></clipPath></defs>';
 for(let i=0;i<=5;i++){const xx=110+i*172,tt=w.start+i*span/5;svg+=`<path class="trend-grid" d="M${xx} 25V805"/><text x="${xx}" y="835" text-anchor="middle">${tt.toFixed(1)} s</text>`;}
 svg+='<text x="12" y="23">POSICIÓN · mm</text>';for(const n of [0,50,100]){const yy=180-n*1.3;svg+=`<path class="trend-grid" d="M110 ${yy}H970"/><text x="95" y="${yy+4}" text-anchor="end">${n}</text>`;}
 let paths='';for(const [k,color]of [['A','#477938'],['B','#267d96']]){const d=w.points.map((p,i)=>(i?'L':'M')+x(p.time)+','+(180-p[k]*1.3).toFixed(2)).join(' ');paths+=`<path d="${d}" fill="none" stroke="${color}" stroke-width="3" ${k==='B'?'stroke-dasharray="7 4"':''}/>`;}
 traceKeys.forEach((k,i)=>{const bottom=260+i*55,top=bottom-22;svg+=`<text x="12" y="${top+9}">${labels[i]}</text><text x="97" y="${top+3}" text-anchor="end">1</text><text x="97" y="${bottom+3}" text-anchor="end">0</text><path class="trend-grid" d="M110 ${bottom}H970"/>`;paths+=`<path d="${stepPath(w.points,k,x,v=>v?top:bottom)}" fill="none" stroke="${i<4?'#527742':'#ac6d32'}" stroke-width="2.5"/>`;});
 if(selected)paths+='<path d="M'+x(selected.time)+' 25V805" stroke="#176f9a" stroke-width="2.5"/><text x="'+Math.min(800,Math.max(115,x(selected.time)+8))+'" y="40" fill="#176f9a">CURSOR '+selected.time.toFixed(2)+' s</text>';
 svg+='<text x="12" y="700">PRESIÓN · bar</text>';for(const value of [0,3,6]){const yy=790-value*12;svg+='<path d="M110 '+yy+'H970" stroke="'+(value===3?'#ac6d32':'#d6dfcc')+'" stroke-dasharray="'+(value===3?'5 4':'0')+'"/><text x="95" y="'+(yy+4)+'" text-anchor="end">'+value+'</text>';}
 const pressurePath=w.points.map((p,i)=>(i?'L':'M')+x(p.time)+','+(790-p.pressure*12).toFixed(2)).join(' ');paths+='<path d="'+pressurePath+'" fill="none" stroke="#267d96" stroke-width="2.5"/>';
 svg+=`<g clip-path="url(#trendClip)">${paths}<path d="M${x(s.time)} 25V805" stroke="#384a3b" stroke-dasharray="3 5"/></g><text x="970" y="18" text-anchor="end">SCAN ACTUAL · ${s.time.toFixed(2)} s</text>`;q('#trendChart').innerHTML=svg;q('#trendReadout').textContent=(selected?'Historial · ':'Actual · ')+'P '+shown.pressure.toFixed(2)+' bar · '+`Instante ${shown.time.toFixed(2)} s · A ${(shown.x*100).toFixed(1)} mm · B ${(shown.y*100).toFixed(1)} mm · ${traceKeys.map((k,i)=>labels[i]+'='+Number(shown[k])).join(' · ')}`;};
 const inspect=point=>{if(!point||current?.disabled)return;trace.selected=point;last='';onInspect(point);render();};
 q('#trendCursor').oninput=e=>inspect(selectTrace(trace,Number(e.target.value)));
 for(const [id,dir,event]of [['tracePrev',-1,false],['traceNext',1,false],['tracePrevEvent',-1,true],['traceNextEvent',1,true]])q('#'+id).onclick=()=>inspect(moveTrace(trace,dir,event));
 q('#traceFault').onclick=()=>{const points=tracePoints(trace),fault=points.findLast((p,i)=>i>0&&p.fault&&!points[i-1].fault);if(fault)inspect(fault);};
 q('#traceLive').onclick=()=>{trace.selected=null;last='';onInspect(null);render();};
 q('#trendChart').onclick=e=>{if(current?.disabled)return;const rect=q('#trendChart').getBoundingClientRect(),xx=(e.clientX-rect.left)/rect.width*1000;if(xx<110||xx>970)return;inspect(selectTrace(trace,windowStart+(xx-110)/860*span));};
 q('#trendSpan').onchange=e=>{span=Number(e.target.value);last='';render()};q('#trendPlay').onclick=onPlay;q('#trendScan').onclick=onScan;q('#trendClear').onclick=()=>{if(!current)return;clearTrace(trace);recordTrace(trace,current.s);onInspect(null);render()};
 return {update(s,playing,disabled){if(!trace.size)recordTrace(trace,s);current={s,playing,disabled};render();}};
}
